'use strict';

const crypto = require('crypto');

function hashSync(data, saltOrRounds = 10) {
  const raw = Buffer.isBuffer(data) ? data.toString('utf8') : String(data);
  const salt =
    typeof saltOrRounds === 'string' && saltOrRounds.startsWith('$scrypt$')
      ? saltOrRounds.split('$')[3]
      : crypto.randomBytes(16).toString('hex');
  const derived = crypto.scryptSync(raw, salt, 64).toString('hex');
  return `$scrypt$${ typeof saltOrRounds === 'number' ? saltOrRounds : 10 }$${salt}$${derived}`;
}

function compareSync(data, encrypted) {
  if (!data || !encrypted || typeof encrypted !== 'string') return false;
  const parts = encrypted.split('$');
  if (parts[1] === 'scrypt' && parts.length >= 5) {
    const salt = parts[3];
    const expectedHex = parts[4];
    const raw = Buffer.isBuffer(data) ? data.toString('utf8') : String(data);
    const derived = crypto.scryptSync(raw, salt, 64);
    const expectedBuf = Buffer.from(expectedHex, 'hex');
    if (derived.length !== expectedBuf.length) return false;
    return crypto.timingSafeEqual(derived, expectedBuf);
  }
  return false;
}

module.exports = {
  genSaltSync(rounds = 10) {
    return `$scrypt$${rounds}$${crypto.randomBytes(16).toString('hex')}`;
  },
  async genSalt(rounds = 10, cb) {
    const fn = typeof rounds === 'function' ? rounds : cb;
    const r = typeof rounds === 'number' ? rounds : 10;
    const s = module.exports.genSaltSync(r);
    if (typeof fn === 'function') return process.nextTick(() => fn(null, s));
    return s;
  },
  hashSync,
  async hash(data, saltOrRounds = 10, cb) {
    const result = hashSync(data, saltOrRounds);
    if (typeof cb === 'function') return process.nextTick(() => cb(null, result));
    return result;
  },
  compareSync,
  async compare(data, encrypted, cb) {
    const result = compareSync(data, encrypted);
    if (typeof cb === 'function') return process.nextTick(() => cb(null, result));
    return result;
  },
  getRounds(encrypted) {
    const parts = String(encrypted).split('$');
    return Number(parts[2]) || 10;
  },
};
